"""Explain expanded-data arms and numerical-hierarchy local smoothers in place."""
import hashlib
from pathlib import Path
import sys
import time

import numpy as np

from captured_physical_pressure_review import load_fit
from prepare_method_review_revisions import revised_card, verified_review_receipt
from review_replay_pressure_series import original_weights
from review_water_learning_sequence import binding, canonical, read, require

ROOT = Path(__file__).resolve().parents[2]
DOC = ROOT / 'docs/plans/model-portfolio-migration-v1'
PROJECT = ROOT / 'projects/rheon-model-portfolio-unified-04'
OUTPUT = DOC / 'reports/captured-augmented-local-pressure-method-reviews-01.json'
SPECS = [('C110',42,371214), ('C111',38,371214), ('C112',34,648), ('C113',34,648),
         ('C114',46,648), ('C115',34,648), ('C116',34,27), ('C117',34,9), ('C118',34,648)]


def same_values(a,b):
    return set(a) == set(b) and all(a[n].tobytes() == b[n].tobytes() for n in a)


def run():
    require(not OUTPUT.exists(), 'Preserve original augmented/local source reviews')
    index_path = PROJECT / 'notes/portfolio-index.json'
    index_raw = index_path.read_bytes()
    index = read(index_path)
    work = read(ROOT / 'runs/model-portfolio-migration-v1/discovery/model-worklist-05.json')
    material = {m['id']:m for m in read(ROOT / 'runs/model-portfolio-migration-v1/discovery/pressure-material-01.json')['models']}
    score_path = DOC / 'reports/pressure-common-score-01.json'
    timing_path = DOC / 'reports/pressure-portfolio-GPU-timing-01.json'
    scores, timing = read(score_path)['models'], read(timing_path)['models']
    purposes = {
        'C110':'Add eight native-generated diverse pressure-request parents to the 34-parent physical replay bank while retaining C101 warm parameters and the fixed fitting budget.',
        'C111':'Add four native captures produced under the learned pressure policy and spectrally relabel their requests, testing training exposure to states reached by the candidate policy.',
        'C112':'Establish a tiny local pressure smoother trained directly on raw recorded requests, as a control for post-coarse residual conditioning.',
        'C113':'Train the same tiny local smoother after one frozen numerical multilevel cycle, targeting the remaining correction while retaining original pressure/RHS labels.',
        'C114':'Add 12 manufactured spatial-band parent groups to post-coarse training to vary pressure spectra; these are independent patterns, not 12 additional fluid trajectories.',
        'C115':'Train the tiny smoother inside one differentiable GCR iteration that combines a frozen numerical V-cycle with the learned local proposal.',
        'C116':'Replace the 648-coefficient tiny smoother by a single 27-coefficient 3³ stencil inside the same one-iteration solver-aware objective.',
        'C117':'Test a nine-coefficient separable XYZ stencil, three single-axis convolutions, within the one-iteration numerical/learned training composition.',
        'C118':'Train three successive differentiable GCR iterations with the same 648-coefficient tiny smoother and initialization as the one-iteration control.',
    }
    lessons = {
        'C110':'The eight added trajectories alter the larger-parent sample distribution under a fixed 800-draw budget; they do not add 800 more updates. The common small-grid pressure tail is slightly higher than C108 while equation error is slightly lower. New native training scenes are not independent common-test scenes.',
        'C111':'On-policy here denotes frozen captured states generated by a learned policy and then relabeled, not fresh online data collection during every optimizer update. Four parents contribute 16 snapshots. Their later temporal coverage does not make this pressure-only model a variable-timestep generator.',
        'C112':'A local correction has limited global pressure reach. The common raw-request error is a valid local-candidate diagnostic, but neither its low latency nor its pressure error measures a complete numerical-hierarchy solve.',
        'C113':'The deployed local readout is unchanged while training bases/residuals are conditioned by a V-cycle. Its common raw-request benchmark omits that hierarchy and evaluates a different residual context from fitting. Do not treat this as a complete hybrid-system regression.',
        'C114':'Manufactured spatial spectra broaden component supervision without extending simulated physical duration or independent fluid-scene count. The common benchmark still measures the local predictor on raw requests; evaluate its intended numerical composition separately.',
        'C115':'Training differentiates a CPU numerical hierarchy and CUDA neural correction together, but the common captured predict_pressure entrypoint emits only the local correction. Solver-aware training work must not be presented as deployed work unless the composing solver is actually benchmarked.',
        'C116':'The stencil shrinks learned parameters to 27, but numerical hierarchy and synchronization can dominate full composition cost. Its raw local pressure/equation tails are worse than the tiny-network control on the common cases; complete-solver accuracy remains a distinct question.',
        'C117':'Nine separable coefficients constrain the learned local operator differently from a 27-tap dense stencil. Similar local-only timing/error does not establish equivalence of complete solver convergence or trajectory drift.',
        'C118':'Equal optimizer-update counts hide three times the learned forward and V-cycle work of C115. The three-iteration training loss and local-only deployment diagnostic are different procedures; qualify a complete GPU-neural solver comparison before judging the intervention.',
    }
    rows, notes, facts = [], [], {}
    for name, parents, parameters in SPECS:
        f = load_fit(name, expected_parents=parents, expected_parameters=parameters,
                     work=work, material=material, index=index, score=scores)
        facts[name] = f
        meta, cfg, history, receipt, fine = (f[k] for k in ('metadata','config','history','receipt','fine'))
        model = (f['project'] / 'model.py').read_text()
        augmented = name in ('C110','C111')
        v6 = int(name[1:]) >= 115
        expected_forwards = 4800 if augmented else 7200 if name == 'C118' else 2400
        require(history['optimizer_work']['network_forwards'] == expected_forwards
                and history['optimizer_work']['forward_cells'] == meta['sampled_cells'] * (expected_forwards//2400)
                and receipt['fine_tuning_statistics']['teacher_forwards'] == 0,
                'Actual optimizer neural/voxel/teacher work differs')
        require(cfg['training']['batch_size'] == 1 and cfg['training']['sampling_seed'] == 2026101804
                and cfg['training']['learning_rate'] == (1e-5 if augmented else .001),
                'Original augmented/local optimization schedule differs')
        extra = {}
        if augmented:
            prior, parent_binding = original_weights(material,'C101')
            require(same_values(prior,f['initial']) and fine['training_passes'] == 2 and fine['teacher_weight'] == 0,
                    'Augmentation arm must use exact C101 initialization')
            data_manifest = read(f['inputs']['splits'])
            group = 'diverse-train' if name == 'C110' else 'onpolicy-train'
            require(data_manifest['expansion_group'] == group and data_manifest['retained_v3_parents'] == 34
                    and data_manifest['added_v4_parents'] == (8 if name == 'C110' else 4), 'Actual expansion population differs')
            generation = ROOT / 'experiments/pressure-methods-v4/pack_expansion.py'
            require(binding(generation)['sha256'] == data_manifest['source_sha256'], 'Expansion packer source changed')
            native_receipts = []
            for p in f['parents'][34:]:
                source = ROOT / p['source_receipt']
                source_receipt = read(source)
                require(source_receipt['status'] == 'completed' and source_receipt['native_process']['reaped']
                        and source_receipt['row']['trajectory_id'] == p['trajectory_id']
                        and binding(source)['sha256'] == data_manifest['source_evidence'][p['source_receipt']],
                        'Original terminal native expansion capture differs')
                native_receipts.append(binding(source))
            extra.update(data_generation_source=dict(binding(generation),manifest_slot='splits'),
                added_native_capture_receipts=native_receipts, exact_warm_parent=parent_binding)
            method='A 371,214-parameter F32 linear multiscale pressure CNN plus learned global branch: 370,016 fine coefficients, 63 coarse logits and a 1,135-parameter grid-shape head. Two ordinary internal pressure corrections each apply a residual-gated low-mode cosine proposal and fine neural correction accumulated in F64. Physical q=(rho/h)r is the single neural field input, using fixed C53 scales; dt is scalar validation metadata. This is a pressure-only request, not two physical simulation outputs.'
            context='Both start from exact completed C101 weights. The original 34-parent bank is retained. '
            context += ('Eight additional physical captures cover cubes and rectangles at 8/16 cells per metre, with two snapshots each.' if name == 'C110' else
                        'Four added captures use the learned pressure policy, with four snapshots each at native indices 0/15/59/119; exact spectral request labels are retained separately.')
            objective='The unchanged final/intermediate physical equation-feedback objective uses two neural proposals, early weight 0.05, target 1e-6 and no eight-pass teacher.'
            inference_scope='Complete captured two-correction pressure proposal; no velocity/tracer advance.'
        else:
            require(fine['schema'] == 'rheon-multilevel-smoother-objective-v1'
                    and fine['relative_equation_target'] == 1e-6
                    and 'return values*.125+self.layers(values)' in model,
                    'Tiny smoother schema/fixed skip differs')
            objective_source = (f['project'] / 'fine_tuning.py').read_text()
            require('return .25*pressure+.25*gradient_error/gradient_target.clamp_min(1e-100)+.4*equation+.1*maximum' in objective_source,
                    'Executed pressure/gradient/equation/maximum weights differ')
            architecture = fine.get('architecture','tiny')
            declared = {'tiny':648,'stencil':27,'separable':9}
            require(declared[architecture] == parameters, 'Independent smoother parameter count differs')
            description = {'tiny':'Three bias-free replicated 3³ convolutions, channels 1→4→4→1',
                           'stencil':'One bias-free replicated 3³ convolution, channels 1→1',
                           'separable':'Three bias-free single-axis length-three convolutions, channels 1→1'}[architecture]
            method=f'{description}, with {parameters} learned F32 coefficients and a fixed residual skip q/8. All layers are linear; F32 execution order remains relevant even when a combined mathematical stencil exists. The input is the normalized physical residual q=(rho/h)r; the F64 reconstructed local pressure correction is cell-zero gauged and added to supplied base pressure. The captured predict_pressure function performs this local readout only; it does not run a V-cycle, GCR, advection or a full simulation advance.'
            if v6:
                iterations = 3 if name == 'C118' else 1
                require(fine['solver_training_iterations'] == iterations
                        and receipt['fine_tuning_statistics']['coarse_cycles'] == 2400*iterations
                        and receipt['fine_tuning_statistics']['network_forwards'] == 2400*iterations
                        and 'residual.to(\'cpu\')' in objective_source and 'for _sweep in range(2):' in objective_source,
                        'Actual differentiable solver training work differs')
                context=f'Training executes {iterations} differentiable flexible GCR iteration(s): each combines a frozen F64 CPU variational V-cycle and a CUDA neural correction, with true-residual recomputation and two orthogonalization sweeps. The explicit first-order adjoint includes the output-gauge transpose; no gradient is deliberately detached at CPU transfers. '
                if name == 'C118':
                    adjoint = (f['project'] / 'adjoint_multilevel.py').read_text()
                    require('adjoint[:,:,0,0,0]-=gradient.sum((2,3,4))' in adjoint and '@once_differentiable' in adjoint,
                            'Explicit first-order gauge transpose differs')
                else:
                    require('import training_multilevel as mg' in objective_source, 'Single-iteration numerical hierarchy owner differs')
                    context=f'Training executes one differentiable flexible GCR iteration combining the original frozen F64 CPU V-cycle and a CUDA neural correction, with true-residual recomputation. Its first coarse residual is independent of neural parameters; there is no subsequent learned-dependent V-cycle requiring the later custom adjoint. '
                objective='At every training iteration, loss weights are pressure 0.25, pressure-gradient 0.25, equation 0.4 and spatial maximum-equation 0.1, plus log1p(relative equation squared/1e-12); iteration losses are averaged.'
                extra['recorded_training_Vcycles'] = 2400*iterations
            else:
                cycles = 0 if name == 'C112' else 1
                require(fine['coarse_training_cycles'] == cycles, 'Original post-coarse training policy differs')
                data_source = (f['project'] / 'data.py').read_text()
                require('delta=mg.correction(initial,h,rho)' in data_source
                        and 'label_policy=' in data_source, 'Executed frozen input conditioning differs')
                context=('Raw original base/residual fields enter fitting.' if cycles == 0 else
                         f'Before fitting, the source materializes one frozen CPU numerical V-cycle for each of the {meta["actual_training_frames"]} saved frames, replacing base/residual while retaining original reference pressure and RHS labels. This preprocessing is outside the learned graph.')
                objective='The local objective weights pressure 0.25, pressure-gradient 0.25, equation 0.4 and spatial maximum-equation 0.1, plus log1p(relative equation squared/1e-12).'
            hierarchy = (f['project'] / 'training_multilevel.py').read_text()
            require('p.T@m@p' in hierarchy and 'p.T@k@p' in hierarchy and 'for _ in range(3):' in hierarchy
                    and 'torch.linalg.cholesky(matrix[1:,1:])' in hierarchy,
                    'Original numerical hierarchy differs')
            if name == 'C114':
                data_manifest = read(f['inputs']['splits'])
                require(data_manifest['added_spectral_parents'] == 12
                        and all(p['source'] == 'operator-generated-spatial-band' for p in f['parents'][34:]),
                        'Manufactured pattern groups must not become extra fluid trajectories')
                pattern = ROOT / 'experiments/pressure-methods-v5/spectrum.py'
                require(binding(pattern)['sha256'] == data_manifest['pattern_source_sha256'], 'Original spatial pattern generator differs')
                extra['spatial_pattern_generator'] = binding(pattern)
                context += ' Twelve added parent groups contain 24 independently manufactured cosine-mode pressure patterns across four shapes and three spatial bands. Their frame/time slots do not denote evolved fluid trajectories.'
            inference_scope='Local smoother only on the common raw requests. Numerical hierarchy/GCR composition is excluded and requires a separate complete-solver benchmark.'
        common, perf = scores[name]['worst'], timing[name]['summary']
        require(timing[name]['weights_sha256'] == receipt['outputs']['weights.npz']['sha256'], 'Retained timing checkpoint differs')
        row = dict(meta, **extra, common_score_source=binding(score_path), retained_timing=binding(timing_path),
            common_benchmark_scope=inference_scope, intended_solver_composition_freshly_benchmarked=False,
            fine_network_forwards=expected_forwards, fine_network_forward_cells=history['optimizer_work']['forward_cells'],
            method=method, purpose=purposes[name],
            experiment=f'2,400 CUDA Adam updates, batch one, clip norm one; fine rate {cfg["training"]["learning_rate"]:g} with captured late drops. There are {parents} parent groups / {meta["actual_training_frames"]} saved examples, all train-only. The sampler preserves 1,600 small draws and interleaves 800 larger-tier draws; exact parent/frame exposures and voxel work verify. Grids extend through 128³ at 8/16/32 cells per metre, with fixed dt=1/60 s and fluid density 1,000 kg/m³. {context} {objective} Captured learning work is {expected_forwards:,} root neural forwards / {history["optimizer_work"]["forward_cells"]:,} input voxels; inherited auxiliary banks and the old teacher are inactive.',
            outcome=f'Retained final logged training loss {history["history"][-1]["loss"]:.17g}. The existing common 128-request result has worst mean-free pressure relative L2 {common["pressure_mean_free_relative_l2"]:.17g}, equation relative L2 {common["common_equation_relative_l2"]:.17g} and GPU median of case-median pressure calls {perf["median_case_median_ms"]:.17g} ms. Scope: {inference_scope} Timings include host-owned input/output, validation/packing, transfers and synchronization for the captured readout, with setup/scoring separate. These are retained consumed small-grid cases, not independent large-grid or trajectory results. No new model execution occurs here.',
            lesson=lessons[name],
            reproduction='Retain the exact typed native recipe, all witnessed source/config/runtime, fixed normalization, complete original input packet, source population and initial/final tensors. Preserve balanced private RNG streams, physical parent/frame counts and final-update selection. Retain native augmentation receipts or manufactured-pattern generator as applicable; post-coarse and differentiable hierarchy training require their exact numerical arithmetic and gauge/adjoint. The historical wrapper/restore runs CPU neural inference and needs a qualified GPU-only route before replay. Clean retraining, new-Rheon regeneration, complete-composition benchmarking and drift remain unqualified; no historical Trial ancestry is invented.')
        raw = (PROJECT / row['note_path']).read_bytes()
        original = verified_review_receipt(row)
        revised, suffix = revised_card(raw,row)
        require(raw.count(original) == revised.count(original) == 1 and revised.endswith(suffix), 'Original augmented/local facts changed')
        rows.append(row)
        notes.append(binding(PROJECT / row['note_path']))
    require(same_values(facts['C110']['initial'],facts['C111']['initial'])
            and same_values(facts['C112']['initial'],facts['C113']['initial'])
            and same_values(facts['C113']['initial'],facts['C114']['initial'])
            and same_values(facts['C115']['initial'],facts['C118']['initial']), 'Expected matched initial tensors differ')
    for a,b in [('C112','C113'),('C115','C116'),('C115','C117'),('C115','C118')]:
        require(np.array_equal(facts[a]['order'],facts[b]['order']), 'Expected matched physical sample order differs')
    require(index_path.read_bytes() == index_raw and all(binding(ROOT / n['path']) == n for n in notes)
            and 'torch' not in sys.modules, 'Read-only/no-neural review invariant failed')
    result = dict(schema='rheon.captured-model-method-reviews.v1', created_unix=time.time(), rows=rows,
        source_reviewed_fits=9, original_note_bindings=notes, local_only_common_benchmark_labels=list(facts)[2:],
        new_model_forwards=0, native_mutations=0, new_reference_generation=False, clean_reproduction_qualified=False,
        producer=binding(Path(__file__)), helpers=[binding(Path(__file__).with_name(n)) for n in
            ['captured_physical_pressure_review.py','captured_replay_pressure_review.py','review_replay_pressure_series.py',
             'prepare_method_review_revisions.py','review_water_learning_sequence.py']])
    OUTPUT.write_bytes(canonical(result) + b'\n')
    print('Nine augmented/local fits reviewed; native versus manufactured data and local versus composed work kept distinct.')


if __name__ == '__main__':
    run()
